INSERT INTO bands (id, user_id, band_name, formation_year, main_genre, basecamp_location, bio, whatsapp_number) VALUES
(1, 201, 'Modjoermakmoer', 2021, 'Indie Pop', 'Jakarta Selatan', 'Band pop sore-sore dengan chorus hangat dan aransemen gitar jangly.', '08224000201'),
(2, 202, 'Distorsi Halus', 2022, 'Alternative Rock', 'Bandung', 'Alternative rock dengan fuzz manis, vokal melodis, dan setlist energik.', '08224000202'),
(3, 203, 'Ruang Reverb', 2020, 'Dream Pop', 'Yogyakarta', 'Unit dream pop yang banyak memakai reverb, chorus, dan synth pad.', '08224000203'),
(4, 204, 'Orkes Kawat', 2019, 'Folk Pop', 'Semarang', 'Folk pop akustik dengan sentuhan violin dan perkusi ringan.', '08224000204'),
(5, 205, 'Nada Garasi', 2023, 'Garage Rock', 'Surabaya', 'Garage rock lugas, latihan cepat, dan siap manggung di skena kampus.', '08224000205'),
(6, 206, 'Terminal Chorus', 2024, 'City Pop', 'Tangerang', 'City pop modern dengan bass groovy, electric piano, dan hook cerah.', '08224000206'),
(7, 207, 'Lautan Fuzz', 2018, 'Stoner Rock', 'Malang', 'Riff berat, tempo santai, dan ampli fuzz yang jadi identitas utama.', '08224000207'),
(8, 208, 'Pita Magnetik', 2021, 'Synth Pop', 'Depok', 'Synth pop retro dengan drum machine, bass analog, dan vokal dreamy.', '08224000208'),
(9, 209, 'Sirkuit Melodi', 2022, 'Pop Punk', 'Bekasi', 'Pop punk cepat dan sing-along, cocok untuk gig sekolah dan kampus.', '08224000209'),
(10, 210, 'Afterclass Riot', 2024, 'Punk Rock', 'Bogor', 'Band punk rock after-school dengan energi mentah dan lagu singkat.', '08224000210')
INSERT INTO vacancies (band_id, title, project_type, needed_instrument, description, status) VALUES
(1, 'Cari Keyboardist untuk Single Baru', 'Recording', 'Keyboard', 'Butuh keyboardist yang bisa isi pad, piano, dan sedikit synth lead untuk satu single indie pop.', 'Open'),
(1, 'Bassist Tetap untuk Gig Bulanan', 'Permanent', 'Bass', 'Modjoermakmoer butuh bassist tetap yang bisa latihan malam dan siap gig sebulan dua kali.', 'Open'),
(2, 'Drummer Rock Alternatif', 'Permanent', 'Drum', 'Distorsi Halus mencari drummer dengan pukulan solid dan bisa main pakai click.', 'Open'),
(2, 'Lead Guitar Session', 'Session', 'Gitar', 'Butuh gitaris lead untuk isi solo dan ambience di dua lagu demo.', 'Closed'),
(3, 'Vokalis Dream Pop', 'Permanent', 'Vokal', 'Ruang Reverb mencari vokalis dengan karakter lembut dan suka eksplorasi lirik dreamy.', 'Open'),
(3, 'Synth Player Live', 'Gig', 'Keyboard', 'Dibutuhkan synth player untuk live set 30 menit di acara kampus.', 'Open'),
(4, 'Violin Player untuk Folk Set', 'Session', 'Violin', 'Orkes Kawat butuh violin player untuk menambah warna di tiga lagu folk pop.', 'Open'),
(4, 'Perkusi Cajon', 'Gig', 'Perkusi', 'Butuh pemain cajon untuk acoustic night akhir pekan.', 'Open'),
(5, 'Vokalis Garage Rock', 'Permanent', 'Vokal', 'Nada Garasi mencari vokalis yang percaya diri, tidak takut panggung kecil, dan suka musik cepat.', 'Open'),
(6, 'Bassist Groovy City Pop', 'Permanent', 'Bass', 'Terminal Chorus butuh bassist dengan feel funk dan groove rapat.', 'Open'),
(6, 'Saxophone untuk Intro Lagu', 'Recording', 'Saxophone', 'Sesi rekaman singkat untuk intro dan bridge single city pop.', 'Open'),
(7, 'Drummer Stoner Rock', 'Permanent', 'Drum', 'Lautan Fuzz mencari drummer yang stabil main tempo lambat dan riff berat.', 'Open'),
(8, 'Vokalis Synth Pop', 'Permanent', 'Vokal', 'Pita Magnetik mencari vokalis yang nyaman dengan backing track dan synth pop retro.', 'Open'),
(9, 'Gitaris Rhythm Pop Punk', 'Permanent', 'Gitar', 'Sirkuit Melodi butuh gitaris rhythm untuk power chord cepat dan backing vocal.', 'Open'),
(10, 'Bassist Punk Rock', 'Permanent', 'Bass', 'Afterclass Riot mencari bassist yang bisa latihan setelah jam sekolah/kuliah.', 'Open');
